180	class VersionManager {
181	 public:
182	  using Ptr = std::shared_ptr<VersionManager>;
183	
184	  static Result<VersionManager::Ptr> Recovery(const std::string &path);
185	
186	  static Result<VersionManager::Ptr> Create(const std::string &path,
187	                                            const Version &initial_version);
188	
189	 private:
190	  VersionManager(const std::string &path, const Version &initial_version,
191	                 uint64_t version_id = 0);
192	
193	 public:
194	  Version get_current_version();
195	
196	  // overwrite the current version
197	  Status apply(const Version &version);
198	
199	  Status reset_writing_segment_meta(SegmentMeta::Ptr meta);
200	
201	  Status add_persisted_segment_meta(SegmentMeta::Ptr meta);
202	
203	  Status remove_persisted_segment_meta(SegmentID id);
204	
205	  Status flush();
206	
207	  void set_id_map_path_suffix(uint32_t suffix) {
208	    std::lock_guard lock(mtx_);
209	    current_version_.set_id_map_path_suffix(suffix);
210	  }
211	
212	  void set_delete_snapshot_path_suffix(uint32_t suffix) {
213	    std::lock_guard lock(mtx_);
214	    current_version_.set_delete_snapshot_path_suffix(suffix);
215	  }
216	
217	  uint32_t delete_snapshot_path_suffix() const {
218	    std::lock_guard lock(mtx_);
219	    return current_version_.delete_snapshot_path_suffix();
220	  }
221	
222	  void set_next_segment_id(SegmentID id) {
223	    std::lock_guard lock(mtx_);
224	    current_version_.set_next_segment_id(id);
225	  }
226	
227	  void set_enable_mmap(bool enable_mmap) {
228	    std::lock_guard lock(mtx_);
229	    current_version_.set_enable_mmap(enable_mmap);
230	  }
231	
232	 private:
233	  const std::string path_;
234	  Version current_version_;
235	  mutable std::mutex mtx_;
236	
237	  uint64_t version_id_ = 0;
238	};
